// Sesuaikan dengan config/app.php > ingest_key di Laragon.
// UBAH sebelum digunakan di jaringan apa pun yang tidak tepercaya.
const API_KEY = "ISI_INGEST_KEY_DARI_CONFIG_APP_PHP";
// Node-RED dan Laragon berjalan pada laptop yang sama:
const API_URL = "http://127.0.0.1/halocake/api/ingest.php";

let payload = msg.payload;
if (Buffer.isBuffer(payload)) payload = payload.toString("utf8");
if (typeof payload === "string") {
    try { payload = JSON.parse(payload); }
    catch (e) { node.warn("Bukan JSON: " + e.message); return null; }
}
if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    node.warn("Payload MQTT harus objek JSON"); return null;
}
if (payload.statusSistem === undefined || payload.statusPalang === undefined ||
    payload.sensor1 === undefined || payload.sensor2 === undefined ||
    payload.jumlahGerbong === undefined) {
    node.warn("Field wajib tidak lengkap: " + JSON.stringify(payload)); return null;
}
// Batas field JSON yang dikirim ke backend; countdown bukan field database.
const output = {
    statusSistem: payload.statusSistem,
    statusPalang: payload.statusPalang,
    sensor1: payload.sensor1,
    sensor2: payload.sensor2,
    jumlahGerbong: payload.jumlahGerbong
};
msg.url = API_URL;
msg.method = "POST";
msg.headers = {"Content-Type":"application/json", "X-API-Key":API_KEY};
msg.payload = JSON.stringify(output);
return msg;
